@namespace sv_4997e88d31794710b2ac108b3ee38a5e.Components.Settings

<nav class="settings-sidebar">
    <h5 class="sidebar-heading">Settings</h5>
    <ul class="nav flex-column">
        @foreach (var section in Sections)
        {
            <li class="nav-item">
                <button class="nav-link @(ActiveSection == section.Key ? "active" : "")"
                        @onclick="() => OnSectionChanged.InvokeAsync(section.Key)">
                    <span class="section-icon">@section.Icon</span>
                    @section.Label
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter, EditorRequired]
    public string ActiveSection { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<string> OnSectionChanged { get; set; }

    private record SectionInfo(string Key, string Label, string Icon);

    private static readonly SectionInfo[] Sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨")
    ];
}

.settings-sidebar {
    padding: 1.5rem 0;
}

.sidebar-heading {
    padding: 0 1rem 0.75rem;
    font-weight: 600;
    color: var(--bs-body-color);
    border-bottom: 1px solid var(--bs-border-color);
    margin-bottom: 0.5rem;
}

.nav-link {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.6rem 1rem;
    color: var(--bs-body-color);
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    border-radius: 0.375rem;
    margin: 0.125rem 0.5rem;
    cursor: pointer;
    font-size: 0.95rem;
    transition: background-color 0.15s;
}

.nav-link:hover {
    background-color: var(--bs-tertiary-bg);
}

.nav-link.active {
    background-color: var(--bs-primary);
    color: #fff;
    font-weight: 500;
}

.section-icon {
    font-size: 1.1rem;
}

