@page "/settings"
@using sv_4997e88d31794710b2ac108b3ee38a5e.Components.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <div class="settings-nav">
        <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="section => _activeSection = section" />
    </div>
    <div class="settings-content">
        @switch (_activeSection)
        {
            case "profile":
                <ProfileSection />
                break;
            case "notifications":
                <NotificationsSection />
                break;
            case "security":
                <SecuritySection />
                break;
            case "appearance":
                <AppearanceSection />
                break;
        }
    </div>
</div>

@code {
    private string _activeSection = "profile";
}

.settings-dashboard {
    display: flex;
    gap: 2rem;
    min-height: 70vh;
}

.settings-nav {
    flex: 0 0 220px;
    border-right: 1px solid var(--bs-border-color);
}

.settings-content {
    flex: 1;
    min-width: 0;
    padding: 1rem 0;
}

.settings-section {
    max-width: 800px;
}

@media (max-width: 768px) {
    .settings-dashboard {
        flex-direction: column;
        gap: 0;
    }

    .settings-nav {
        flex: none;
        border-right: none;
        border-bottom: 1px solid var(--bs-border-color);
    }
}

